plist.dict:
CFBundlePackageType
APPL
CFBundleName
{{.Info.ProductName}}

CFBundleDisplayName
{{.Info.ProductName}}
CFBundleExecutable
{{.OutputFilename}}
CFBundleIdentifier
com.podsteer.desktop
CFBundleVersion
{{.Info.ProductVersion}}
CFBundleGetInfoString
{{.Info.Comments}}
CFBundleShortVersionString
{{.Info.ProductVersion}}
CFBundleIconFile
iconfile
LSMinimumSystemVersion
10.13.0
NSHighResolutionCapable
true
NSHumanReadableCopyright
{{.Info.Copyright}}

NSDocumentsFolderUsageDescription
PodSteer reads this only if your kubeconfig, or a certificate it names, is stored in your Documents folder.
NSDesktopFolderUsageDescription
PodSteer reads this only if your kubeconfig, or a certificate it names, is stored on your Desktop.
NSDownloadsFolderUsageDescription
PodSteer reads this only if your kubeconfig, or a certificate it names, is stored in your Downloads folder.
NSNetworkVolumesUsageDescription
PodSteer reads this only if your kubeconfig, or a certificate it names, is stored on a network volume.
NSRemovableVolumesUsageDescription
PodSteer reads this only if your kubeconfig, or a certificate it names, is stored on a removable volume.
{{if .Info.FileAssociations}}
CFBundleDocumentTypes

  {{range .Info.FileAssociations}}

    CFBundleTypeExtensions

      {{.Ext}}

    CFBundleTypeName
    {{.Name}}
    CFBundleTypeRole
    {{.Role}}
    CFBundleTypeIconFile
    {{.IconName}}

  {{end}}

{{end}}
{{if .Info.Protocols}}
CFBundleURLTypes

  {{range .Info.Protocols}}

        CFBundleURLName
        com.wails.{{.Scheme}}
        CFBundleURLSchemes

            {{.Scheme}}

        CFBundleTypeRole
        {{.Role}}

  {{end}}

{{end}}
NSAppTransportSecurity

    NSAllowsLocalNetworking
